const items = $input.all();
if (!items.length || !items[0].json.msg_id) return [];
return items.map(i => {
  const msg = typeof i.json.message === 'string' ? JSON.parse(i.json.message) : i.json.message;
  return { json: { ...i.json, ...msg } };
});

const resp = $input.first().json;
const canonical = $('Load Canonical Order').item.json;
const parse = $('Parse Messages').item.json;
const key = $('Load Shipday Key').item.json.shipday_api_key;
const statusCode = resp.statusCode || resp.status || 0;
const body = resp.body ?? resp.data ?? resp;
let idempotency_skip = false;
let existing_shipday_order_id = null;
if (statusCode === 200 && body) {
  if (Array.isArray(body) && body.length && body[0].orderId) {
    idempotency_skip = true;
    existing_shipday_order_id = String(body[0].orderId);
  } else if (body.orderId) {
    idempotency_skip = true;
    existing_shipday_order_id = String(body.orderId);
  }
}
return [{ json: {
  idempotency_skip,
  existing_shipday_order_id,
  canonical_id: canonical.id,
  external_ref: canonical.external_ref,
  location_key: canonical.location_key,
  correlation_id: canonical.correlation_id,
  msg_id: parse.msg_id,
  shipday_api_key: key,
  customer: canonical.customer,
  items: canonical.items,
  payment: canonical.payment,
  restaurant_name: canonical.restaurant_name,
  restaurant_address: canonical.restaurant_address,
  restaurant_phone: canonical.restaurant_phone,
  gps_lat: canonical.gps_lat,
  gps_lng: canonical.gps_lng
}}];

const inp = $input.first().json;
const customer = inp.customer || {};
const addr = customer.address || {};
const payment = inp.payment || {};
const items = inp.items || [];
const pad = n => String(n).padStart(2, '0');
// Shipday expects UTC: date yyyy-mm-dd, times hh:mm:ss (see SHIPDAY-API-REFERENCE.md)
const fmtTime = d => `${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}`;
const fmtDate = d => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
const now = new Date();

// Promised times from JET (restaurant_estimated_*) instead of hardcoded now+20/+45 —
// pre-orders used to hit the dispatch board hours early with a bogus ETA.
function parseFuture(iso, minAheadMs) {
  if (!iso) return null;
  const t = new Date(iso);
  return (!isNaN(t.getTime()) && t.getTime() > now.getTime() + minAheadMs) ? t : null;
}
const promisedDelivery = parseFuture(inp.raw_est_delivery, 5 * 60 * 1000) || new Date(now.getTime() + 45 * 60 * 1000);
const promisedPickup = parseFuture(inp.raw_est_pickup, 0)
  || new Date(Math.max(promisedDelivery.getTime() - 25 * 60 * 1000, now.getTime() + 10 * 60 * 1000));

// Address: house number lives inside line1 (JET) or line2 (Shopify) — join street parts
// with spaces, then locality. Country code → full name for geocoding.
const COUNTRY = { BE: 'Belgium', NL: 'Netherlands', FR: 'France', DE: 'Germany' };
const street = [addr.line1, addr.line2].filter(Boolean).join(' ').trim();
const locality = [addr.postal_code, addr.city].filter(Boolean).join(' ').trim();
const customerAddress = [street, locality, COUNTRY[addr.country] || addr.country].filter(Boolean).join(', ');

const totalCents = payment.total_cents || 0;
const paymentMethod = (payment.method === 'cash') ? 'cash' : 'credit_card';
const orderItem = items.map(it => ({
  name: it.name || it.title || 'Item',
  quantity: it.qty || it.quantity || 1,
  unitPrice: ((it.unit_price_cents || 0) / 100),
  detail: it.notes || ''
}));
const payload = {
  orderNumber: inp.external_ref,
  customerName: customer.name || 'Customer',
  customerAddress: customerAddress || 'Unknown',
  customerPhoneNumber: customer.phone || '',
  customerEmail: customer.email || '',
  restaurantName: inp.restaurant_name,
  restaurantAddress: inp.restaurant_address,
  restaurantPhoneNumber: inp.restaurant_phone || '',
  expectedDeliveryDate: fmtDate(promisedDelivery),
  expectedPickupTime: fmtTime(promisedPickup),
  expectedDeliveryTime: fmtTime(promisedDelivery),
  pickupLatitude: inp.gps_lat,
  pickupLongitude: inp.gps_lng,
  totalOrderCost: totalCents / 100,
  paymentMethod,
  deliveryInstruction: customer.notes || '',
  orderSource: 'Srova Data',
  additionalId: inp.canonical_id,
  orderItem
};
// Precise dropoff coords when the source provided them — stops Shipday geocoding guesses.
if (addr.lat != null && addr.lng != null) {
  payload.deliveryLatitude = addr.lat;
  payload.deliveryLongitude = addr.lng;
}
return [{ json: {
  payload,
  canonical_id: inp.canonical_id,
  external_ref: inp.external_ref,
  location_key: inp.location_key,
  correlation_id: inp.correlation_id,
  msg_id: inp.msg_id,
  shipday_api_key: inp.shipday_api_key
}}];

const resp = $input.first().json;
const input = $('Build Shipday Payload').item.json;
const statusCode = resp.statusCode || resp.status || resp.error?.status || 0;
const body = resp.body ?? resp.data ?? resp;
let action, alert = false, validationError = null;
let shipday_order_id = null;
if (statusCode === 200 || statusCode === 201) {
  action = 'success';
  if (body && body.orderId) shipday_order_id = String(body.orderId);
} else if (statusCode === 401) {
  action = 'retry';
} else if (statusCode === 400) {
  action = 'dlq';
  alert = true;
  validationError = resp.error?.message || body;
} else if (statusCode === 403) {
  action = 'dlq';
  alert = true;
} else if (statusCode >= 500 || statusCode === 429 || statusCode === 0) {
  action = 'retry';
} else {
  action = 'dlq';
  alert = true;
}
return [{ json: {
  action,
  alert,
  validationError,
  shipday_order_id,
  statusCode,
  canonical_id: input.canonical_id,
  external_ref: input.external_ref,
  location_key: input.location_key,
  correlation_id: input.correlation_id,
  msg_id: input.msg_id
}}];
